//
// The official "VR Address Library for SKSEVR" (version-1-4-15-0.csv) only covers
// ~13,288 of the addresses this project needs. These entries fill the gap: each was
// derived by taking this project's existing SSE address-library id, resolving it to
// an SSE virtual address via the SSE address library offsets, then cross-referencing
// that address against a community SSE<->VR binary-diff table (vr_address_tools'
// sse_vr.csv) to find the matching VR virtual address, which is then converted back
// to a module-relative offset. This is inferred from binary diffing, not from the
// authoritative VR address library, so treat it as high-confidence but not gospel -
// validated against the ~9 ids that exist in both official libraries (exact match).
//
// VersionDb::LoadCSV() merges these in to fill any id missing from the official CSV;
// official entries always take precedence.
struct VRAddressOverrideEntry
{
    uint32_t id;
    uint32_t offset;
};

